<table class="table"><thead><tr><th><?= e(_l('subject')); ?></th><th><?= e(_l('status')); ?></th><th><?= e(scaf_rep_label('Signature proof','Prueba de firma')); ?></th></tr></thead><tbody><?php foreach($contracts as $c){$proof=scaf_rep_signature($c); ?><tr><td><a href="<?= e(admin_url('sales_center/contract_view/'.(int)$c['id'])); ?>"><?= e($c['subject']); ?></a></td><td><?= e($c['status']); ?></td><td><span class="scaf-signature-state scaf-signature-<?= e($proof); ?>"><?= e($proof==='both'?scaf_rep_label('Signed & countersigned','Firmado y contrafirmado'):($proof==='partial'?scaf_rep_label('Awaiting countersignature','Pendiente de contrafirma'):scaf_rep_label('No verified signature record','Sin registro de firma verificada'))); ?></span></td></tr><?php } ?></tbody></table></section>
